    })
  })
  output$survival_table_events <- gt::render_gt({
    getSurvivalTableEvents()
  })
  output$survival_table_events_download <- shiny::downloadHandler(
    filename = paste0("table_survival_events.", input$survival_table_events_format),
    content = function(file) {
      gt::gtsave(getSurvivalTableEvents(), file)
    }
  )
  getSurvivalTableAttrition <- shiny::reactive({
    result <- getSurvivalData("survival_attrition", useReason = TRUE, useFollowUpSettings = FALSE)
    safeTable(result, function(x) {
      CohortSurvival::tableSurvivalAttrition(
        x,
        type = "gt"
      )
    })
  })
  output$survival_table_attrition <- gt::render_gt({
    getSurvivalTableAttrition()
  })
  output$survival_table_attrition_download <- shiny::downloadHandler(
    filename = paste0("table_survival_attrition.", input$survival_table_attrition_format),
    content = function(file) {
      gt::gtsave(getSurvivalTableAttrition(), file)
    }
  )
  getSurvivalPlotSurvival <- shiny::reactive({
    applied <- appliedSurvivalInputs()
    shiny::req(applied)
    isCompetingRisk <- identical(applied$analysis_type, "competing_risk")
    result <- getSurvivalData("survival_estimates", useStrata = TRUE)

    shiny::validate(
      shiny::need(
        nrow(result) > 0,
        "No survival estimates available for the selected filters."
      )
    )

    result |>
      CohortSurvival::plotSurvival(
        facet = input$survival_plot_survival_facet,
        colour = input$survival_plot_survival_colour,
        cumulativeFailure = isCompetingRisk || input$survival_plot_survival_cumulative_failure,
        logLog = input$survival_plot_survival_log_log,
        timeScale = input$survival_plot_survival_time_scale
      )
  })
  output$survival_plot_survival <- shiny::renderUI({
    x <- getSurvivalPlotSurvival()
    renderInteractivePlot(x, input$survival_plot_survival_interactive)
  })
  output$survival_plot_survival_download <- shiny::downloadHandler(
    filename = "plot_survival.png",
    content = function(file) {
      ggplot2::ggsave(
        filename = file,
        plot = getSurvivalPlotSurvival(),
        width = as.numeric(input$survival_plot_survival_width),
        height = as.numeric(input$survival_plot_survival_height),
        units = input$survival_plot_survival_units,
        dpi = as.numeric(input$survival_plot_survival_dpi)
      )
    }
  )

  # summarise_log_file -----
  ## update message if filter is changed
  shiny::observe({
    if (renderState$summarise_log_file == "rendered") {
      renderState$summarise_log_file <- "stale"
    }
  }) |>
    shiny::bindEvent(
      input$summarise_log_file_cdm_name,
      input$summarise_log_file_variable_name,
      ignoreInit = TRUE
    )
  output$update_message_summarise_log_file <- shiny::renderUI({
    switch(renderState$summarise_log_file,
      initial = updateInitialMessage,
      stale = updateMessage,
      rendered = NULL
    )
  })
  shiny::observeEvent(input$update_summarise_log_file,
    {
      renderState$summarise_log_file <- "rendered"
    },
    ignoreInit = TRUE
  )

  ## get summarise_log_file data
  getSummariseLogFileData <- shiny::eventReactive(input$update_summarise_log_file,
    {
      data[["summarise_log_file"]] |>
        dplyr::filter(
          .data$cdm_name %in% input$summarise_log_file_cdm_name,
          .data$variable_name %in% input$summarise_log_file_variable_name
        )
    },
    ignoreInit = TRUE
  )
  getSummariseLogFileTable <- shiny::reactive({
    getSummariseLogFileData() |>
      dplyr::filter(.data$estimate_name == "date_time") |>
      visOmopResults::visOmopTable(
        header = "cdm_name",
        hide = c("variable_level", "estimate_name")
      )
  })
  output$summarise_log_file_table <- gt::render_gt({
    getSummariseLogFileTable()
  })
  output$summarise_log_file_table_download <- shiny::downloadHandler(
    filename = paste0("table_log.", input$summarise_log_file_table_format),
    content = function(file) {
      gt::gtsave(getSummariseLogFileTable(), file)
    }
  )
  getSummariseLogFilePlot <- shiny::reactive({
    getSummariseLogFileData() |>
      dplyr::filter(.data$estimate_name == "elapsed_time") |>
      visOmopResults::barPlot(
        x = c("log_id", "variable_name"),
        y = "elapsed_time",
        colour = "cdm_name",
        position = input$summarise_log_file_plot_position
      )
  })
  output$summarise_log_file_plot <- shiny::renderUI({
    tryCatch(
      {
        x <- getSummariseLogFilePlot()
        renderInteractivePlot(x, input$summarise_log_file_plot_interactive)
      },
      error = function(e) {
        if (inherits(e, "shiny.silent.error")) stop(e)
        shiny::div(class = "alert alert-danger text-white d-flex align-items-start gap-2", shiny::icon("triangle-exclamation", class = "mt-1"), shiny::div(class = "error-message", conditionMessage(e)))
      }
    )
  })
  output$summarise_log_file_plot_download <- shiny::downloadHandler(
    filename = "plot_logs.png",
    content = function(file) {
      ggplot2::ggsave(
        filename = file,
        plot = getSummariseLogFilePlot(),
        width = as.numeric(input$summarise_log_file_plot_width),
        height = as.numeric(input$summarise_log_file_plot_height),
        units = input$summarise_log_file_plot_units,
        dpi = as.numeric(input$summarise_log_file_plot_dpi)
      )
    }
  )
}
